import 'package:flutter/material.dart';
import '../../../inventory/data/models/inventory_model.dart';
class LowStockItemsCard extends StatelessWidget { const LowStockItemsCard({required this.items, super.key}); final List<InventoryModel> items; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Low Stock Items', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 8), if (items.isEmpty) const Text('All stock levels are healthy') else ...items.take(5).map((i) => ListTile(contentPadding: EdgeInsets.zero, title: Text(i.medicationName ?? ''), subtitle: Text(i.branchName ?? ''), trailing: Text('${i.quantity} left', style: const TextStyle(color: Colors.red))))]))); }
